<?php defined('BASEPATH') or exit('No direct script access allowed'); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo html_escape($title); ?></title><link rel="stylesheet" href="<?php echo module_dir_url('recruitment','assets/css/smart_choice_recruitment_portal.css'); ?>"></head><body class="sc-assessment-body"><main class="sc-assessment-wrap"><header><h1><?php echo _l('recruitment_assessments_title'); ?></h1><p><?php echo _l('recruitment_assessments_intro'); ?></p></header><?php if($submitted){ ?><div class="sc-assessment-success"><h2><?php echo _l('recruitment_assessments_thank_you'); ?></h2><?php foreach($results as $type=>$r){ ?><p><strong><?php echo html_escape($sets[$type]['title']); ?>:</strong> <?php echo html_escape($r['score']); ?>% — <?php echo html_escape($r['summary']); ?></p><?php } ?></div><?php }else{ ?><?php echo form_open(current_url()); ?><?php foreach($sets as $type=>$set){ ?><section class="sc-test-card"><h2><?php echo html_escape($set['title']); ?></h2><?php foreach($set['questions'] as $qk=>$q){ ?><fieldset><legend><?php echo html_escape($q['text']); ?></legend><?php foreach($q['options'] as $ok=>$label){ ?><label><input required type="radio" name="answers[<?php echo $type; ?>][<?php echo $qk; ?>]" value="<?php echo $ok; ?>"> <?php echo html_escape($label); ?></label><?php } ?></fieldset><?php } ?></section><?php } ?><button class="sc-rec-primary" type="submit"><?php echo _l('submit'); ?></button><?php echo form_close(); ?><?php } ?></main><style>.sc-assessment-body{margin:0;background:#f5f7f6;font-family:Inter,Segoe UI,Arial,sans-serif;color:#263238}.sc-assessment-wrap{max-width:900px;margin:0 auto;padding:32px 18px 70px}.sc-assessment-wrap header{background:linear-gradient(120deg,#0E6F5B,#169179);color:#fff;padding:30px;border-radius:8px;margin-bottom:22px}.sc-assessment-wrap header h1{color:#fff;margin-top:0}.sc-test-card,.sc-assessment-success{background:#fff;border:1px solid #d9e2df;border-radius:7px;padding:24px;margin-bottom:20px;box-shadow:0 10px 25px rgba(14,111,91,.07)}.sc-test-card fieldset{border:0;border-top:1px solid #e5ece9;padding:18px 0}.sc-test-card legend{font-weight:800;margin-bottom:12px}.sc-test-card label{display:block;padding:8px 0}</style></body></html>